import { Scene } from "retiam";
import { Physics3D } from "retiam/physics";

const scene = new Scene();
const physics = new Physics3D(scene, {
    gravity: [0, -9.81, 0] // Default gravity vector
});

export interface PhysicsBodyOptions {
    type?: 'dynamic' | 'static' | 'kinematicPosition' | 'kinematicVelocity';
    shape?: 'box' | 'sphere' | 'cylinder' | 'capsule' | 'trimesh' | 'convexHull';

    // Physical attributes
    mass?: number;               // Default: 1.0 kg (dynamic)
    friction?: number;           // Default: 0.5 (Coulomb friction coefficient)
    restitution?: number;        // Default: 0.0 (Bounciness [0.0 = clay, 1.0 = superball])
    linearDamping?: number;      // Default: 0.0 (Air resistance on translation)
    angularDamping?: number;     // Default: 0.0 (Air resistance on rotation)

    // Initial kinematics
    velocity?: [number, number, number];        // Initial linear velocity vector [vx, vy, vz]
    angularVelocity?: [number, number, number]; // Initial spin [wx, wy, wz]

    // Shape dimensions (auto-detected if omitted)
    size?: [number, number, number]; // Half-extents for box
    radius?: number;                 // Radius for sphere/cylinder/capsule
    height?: number;                 // Height for cylinder/capsule

    // Continuous Collision Detection (CCD)
    ccd?: boolean; // Prevents fast-moving bodies from tunneling through thin walls
}

// 1. Sphere (Auto-inferred from Sphere primitive)
const ball = new Sphere(0.5, 16, 16, { materialColor: Color.RED });
physics.add(ball, { type: 'dynamic', restitution: 0.8, friction: 0.2 });

// 2. Box / Boundary (Auto-inferred from Box primitive)
const wall = new Box(10, 4, 0.5, { materialColor: Color.GRAY });
physics.add(wall, { type: 'static', restitution: 0.4 });

// 3. Cylinder / Pachinko Peg
const peg = new Cylinder(0.3, 0.3, 4.0, { radialSegments: 16 });
physics.add(peg, { type: 'static', shape: 'cylinder' });

